<script lang="ts">
 import Illustration from './Illustration.svelte';
 import {onMount} from 'svelte';import {fade} from 'svelte/transition';import {prefersReducedMotion} from 'svelte/motion';
 import diagrams from '#lib/locales/de/atlas/style-visuals.json';import Glass from './Glass.svelte';import Icon from '../Icon.svelte';
 let root=$state<HTMLDivElement>();onMount(()=>{if(!root)return;const node=root;const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){node.classList.add('visual-visible');observer.disconnect();}},{threshold:.2});observer.observe(node);return()=>observer.disconnect();});
 let {slug}:{slug:string}=$props();let selected=$state(0);const profile=$derived(diagrams[slug as keyof typeof diagrams]);const choices=$derived(profile&&'layout'in profile&&profile.layout==='choices');
</script>
{#if profile}<div bind:this={root} class="learning-visual wine-style-diagram" data-visual="wine-style"><div class="visual-heading"><span class="eyebrow">{choices?'WEINSTILE VERGLEICHEN':'HERSTELLUNG VERSTEHEN'}</span><h3>{profile.title}</h3></div><div class="style-process" class:illustrated-style={slug==='rotwein'}>{#if slug==='rotwein'}<Illustration kind="rotwein" stage={selected}/>{:else}<Glass color={profile.color} bubbles={profile.bubbles}/>{/if}<div class="style-stage-options" role="group" aria-label={choices?'Wege vergleichen':'Herstellungsschritt auswählen'}>{#each profile.stages as stage,i}<button type="button" aria-pressed={selected===i} class:active={selected===i} onclick={()=>selected=i}>{#if !choices}<span>0{i+1}</span>{/if}{stage.title}{#if !choices}<Icon name="next" size={16}/>{/if}</button>{/each}</div></div>{#key selected}<div class="visual-explanation" in:fade={{duration:prefersReducedMotion.current?0:130}}><h4>{profile.stages[selected].title}</h4><p>{profile.stages[selected].body}</p></div>{/key}{#if choices}<small class="visual-caption">Verschiedene Wege, keine aufeinanderfolgenden Schritte.</small>{/if}</div>{/if}

<style>.style-process.illustrated-style{display:block}.illustrated-style :global(.scene-artwork){margin:0 0 20px}</style>
